    public event PropertyChangedEventHandler? PropertyChanged;
    public string Language { get => _language; private set { _language = value; PropertyChanged?.Invoke(this, new(nameof(Language))); PropertyChanged?.Invoke(this, new("Item[]")); } }
    public IReadOnlyList<LanguageOption> Languages { get; } = [new("System default", ""), new("English", "en"), new("Magyar", "hu"), new("Deutsch", "de"), new("Espa\u00F1ol", "es"), new("Fran\u00E7ais", "fr"), new("Italiano", "it"), new("Polski", "pl")];
    public string this[string key] => Text.TryGetValue(Language, out var dict) && dict.TryGetValue(key, out var value) ? value : English.GetValueOrDefault(key, key);
    public void SetLanguage(string? requested)
    {
        var code = string.IsNullOrWhiteSpace(requested) ? CultureInfo.CurrentUICulture.TwoLetterISOLanguageName : requested.ToLowerInvariant();
        Language = Text.ContainsKey(code) ? code : "en";
        var culture = CultureInfo.GetCultureInfo(Language switch { "hu" => "hu-HU", "de" => "de-DE", "es" => "es-ES", "fr" => "fr-FR", "it" => "it-IT", "pl" => "pl-PL", _ => "en-US" });
        CultureInfo.DefaultThreadCurrentCulture = culture; CultureInfo.DefaultThreadCurrentUICulture = culture;
    }
